import Foundation

@MainActor
extension SharedMediaNativeOriginalOwner {
    /// IDs are caller-owned and fixed before acquiring locks. No fresh identity
    /// is generated by admission or acknowledgement recovery.
    func appReceivingRequest(packageID: UUID, pairIDs: [UUID], operationID: UUID, queueID: UUID,
                             observationID: UUID, bindingID: UUID, generation: UUID, eventID: UUID,
                             timestamp: Date) async throws -> SharedMediaNativeAppReceivingRequest {
        try await withReceivingLocks(queueID: queueID.uuidString, observationID: observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) {
                try await $0.request(packageID: packageID, pairIDs: pairIDs, operationID: operationID, queueID: queueID,
                    observationID: observationID, bindingID: bindingID, generation: generation, eventID: eventID, timestamp: timestamp)
            }
        }
    }
    func receiveAppPhotos(_ request: SharedMediaNativeAppReceivingRequest) async throws -> SharedMediaNativeConsumerCohort {
        try await withReceivingLocks(queueID: request.cohort.originQueueID, observationID: request.cohort.observationID) { lock in
            try await self.appReceivingWorkflow(lock: lock) { try await $0.apply(request) }
        }
    }
    /// Discovery precedes fresh ID generation. A saved slot is immutable even
    /// when its source files are currently unavailable.
    func stageAppReceiving(packageID: UUID, draftGeneration: UUID, pairIDs: [UUID],
                           expectedMetadata: SharedMediaNativeAppMetadataRequest? = nil,
                           photoAdmission: SharedMediaNativePhotoAdmission? = nil) async throws -> SharedMediaNativeReceivingIntent.Prepared {
        let saved = try await discoverAppReceivingIntent(packageID: packageID)
        let identity = try SharedMediaNativeReceivingStageIdentity(saved: saved)
        return try await withReceivingLocks(queueID: identity.queueID.uuidString, observationID: identity.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) {
                try await $0.stage(packageID: packageID, draftGeneration: draftGeneration, pairIDs: pairIDs,
                                   identity: identity, expectedMetadata: expectedMetadata, photoAdmission: photoAdmission)
            }
        }
    }
    /// Called only inside the existing retained dispatch operation. Preflight is
    /// outside receiving locks, but account shutdown still cancels and drains it.
    func stageAppReceivingWithAdmission(metadata: SharedMediaNativeAppMetadataRequest, pairIDs: [UUID],
        authorize: @escaping @MainActor (UUID) async throws -> IdentificationDispatchAuthorization,
        storage: SharedMediaNativeStorageRepository, grant: SharedMediaNativeAppDispatchGrant,
        releaseStage: SharedMediaNativeReleaseStageSettlement) async throws -> SharedMediaNativeReceivingIntent.Prepared {
        let packageID = metadata.package.id, draft = metadata.package.generation
        let saved = try await storage.appReceivingIntent(grant: grant, packageID: packageID)
        let identity = try SharedMediaNativeReceivingStageIdentity(saved: saved)
        var authorization: IdentificationDispatchAuthorization?
        var admission: SharedMediaNativePhotoAdmission?
        if saved == nil {
            let current = try await storage.appMetadata(grant: grant).current(packageID: packageID, draftGeneration: draft)
            guard current.profile == metadata.profile, current.package == metadata.package,
                  current.member == metadata.member, current.envelope == metadata.envelope,
                  metadata.envelope == metadata.package.envelope else { throw SharedMediaStorageFailure.stale }
            let envelope = try SharedMediaNativeDraftEnvelope.decode(metadata.envelope)
            let selected = try envelope.intents.map { try SharedMediaNativeDerivativeIntent.decode($0.bytes).pairID }
            guard (1...2).contains(pairIDs.count), pairIDs == selected else { throw SharedMediaStorageFailure.stale }
            try grant.validate()
            let value = try await authorize(identity.observationID)
            try grant.validate()
            admission = try SharedMediaNativePhotoAdmission(authorization: value)
            authorization = value
        }
        // Saved slots, including legacy nil expectations, never rediscover a recipient.
        return try await withReceivingLocks(queueID: identity.queueID.uuidString, observationID: identity.observationID.uuidString) { lock in
            try grant.validate(); try authorization?.validate()
            let operation = try await storage.appReceiving(grant: grant, lock: lock, releaseStage: releaseStage)
            try lock.validate(); try grant.validate(); try authorization?.validate()
            return try await operation.stage(packageID: packageID, draftGeneration: draft, pairIDs: pairIDs,
                identity: identity, expectedMetadata: metadata, photoAdmission: admission,
                beforeImmutableSave: { try authorization?.validate() })
        }
    }
    func receiveAppPrepared(_ prepared: SharedMediaNativeReceivingIntent.Prepared) async throws -> SharedMediaNativeConsumerCohort {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) { try await $0.receivePrepared(prepared) }
        }
    }
    /// Read frozen received input without making its held queue executable.
    func readReceivedAppPhotos(_ prepared: SharedMediaNativeReceivingIntent.Prepared) async throws -> SharedMediaNativeReceivedPhotoReadback {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appReceivingWorkflow(lock: lock) { try await $0.readReceivedPhotos(prepared) }
        }
    }
    func allocateAppPhoto(_ prepared: SharedMediaNativeReceivingIntent.Prepared, reserveRoleMapping: Bool = false,
                          authorizeCreate: @escaping SharedMediaNativePhotoAllocationAccess.Authorize,
                          send: @escaping SharedMediaNativePhotoAllocationAccess.Send) async throws -> SharedMediaNativePhotoAllocation {
        try await allocateAppPhoto(prepared, reserveRoleMapping: reserveRoleMapping, authorizeCreate: authorizeCreate, transport: .legacy(send))
    }
    func allocateAppPhotoRoles(_ prepared: SharedMediaNativeReceivingIntent.Prepared,
                              authorizeCreate: @escaping SharedMediaNativePhotoAllocationAccess.Authorize,
                              send: @escaping SharedMediaNativePhotoAllocationTransportAccess.RolesSend) async throws -> SharedMediaNativePhotoAllocation {
        try await allocateAppPhoto(prepared, authorizeCreate: authorizeCreate, transport: .roles(send))
    }
    func allocateAppPhoto(_ prepared: SharedMediaNativeReceivingIntent.Prepared,
                          authorizeCreate: @escaping SharedMediaNativePhotoAllocationAccess.Authorize,
                          transport: InitialPhotoAllocationTransport) async throws -> SharedMediaNativePhotoAllocation {
        try await allocateAppPhoto(prepared, authorizeCreate: authorizeCreate, send: { request, validate, settle in
            try await transport.perform(request, validateAttempt: validate, validateResponse: settle)
        })
    }
    /// One retained account/store operation spans authorization and persistence.
    /// Only coordinator locks are released during bounded network requests.
    func allocateAppPhoto(_ prepared: SharedMediaNativeReceivingIntent.Prepared,
        storage: SharedMediaNativeStorageRepository, grant: SharedMediaNativeAppDispatchGrant,
        releaseStage: SharedMediaNativeReleaseStageSettlement, reserveRoleMapping: Bool = false,
        authorizeCreate: @escaping SharedMediaNativePhotoAllocationAccess.Authorize,
        transport: SharedMediaNativePhotoAllocationTransportAccess) async throws -> SharedMediaNativePhotoAllocation {
        let saved = try await withReceivingLocks(queueID: prepared.queueID.uuidString,
            observationID: prepared.observationID.uuidString) { lock in
            try await storage.appPhotoAllocation(grant: grant, lock: lock).saved(prepared)
        }
        var authorization: IdentificationDispatchAuthorization?
        if saved == nil {
            let value = try await authorizeCreate(prepared, { try grant.validate() })
            try grant.validate()
            try SharedMediaNativePhotoAdmission(authorization: value).requireSaved(prepared.photoAdmission)
            authorization = value
        }
        let dispatch = try await withReceivingLocks(queueID: prepared.queueID.uuidString,
            observationID: prepared.observationID.uuidString) { lock in
            try grant.validate()
            var operation = try await storage.appPhotoAllocation(grant: grant, lock: lock)
            if try operation.saved(prepared) == nil {
                guard let authorization else { throw SharedMediaStorageFailure.stale }
                try authorization.validate()
                let receiving = try await storage.appReceiving(grant: grant, lock: lock, releaseStage: releaseStage)
                _ = try await receiving.readReceivedPhotos(prepared)
                operation = try await storage.appPhotoAllocation(grant: grant, lock: lock)
            }
            try grant.validate(); try lock.validate()
            return try operation.claim(prepared, attemptID: UUID(), reserveRoleMapping: reserveRoleMapping || transport.projection == .roles, beforeClaimSave: {
                guard let authorization else { throw SharedMediaStorageFailure.stale }
                try authorization.validate()
            })
        }
        try grant.validate()
        let request = try dispatch.consume(projection: transport.projection)
        let createAuthorization = request.action == .create ? authorization : nil
        let reply = try await transport.send(request, validate: {
            try grant.validate(); try createAuthorization?.validate()
        }, settle: { try grant.validate() })
        try grant.validate()
        return try await withReceivingLocks(queueID: prepared.queueID.uuidString,
            observationID: prepared.observationID.uuidString) { lock in
            let operation = try await storage.appPhotoAllocation(grant: grant, lock: lock)
            try grant.validate(); try lock.validate()
            switch reply {
            case .legacy(let value): return try operation.settle(value, request: request.allocation, prepared: prepared)
            case .roles(let value): return try operation.enrich(value, request: request.allocation, prepared: prepared)
            }
        }
    }
    /// Inactive metadata-only enrichment seam. The retained owner survives the
    /// await; fresh coordinator locks protect each durable transition. There is
    /// no v2 HTTP adapter or create permission at this seam.
    func enrichAppPhotoAllocation(_ prepared: SharedMediaNativeReceivingIntent.Prepared,
        storage: SharedMediaNativeStorageRepository, grant: SharedMediaNativeAppDispatchGrant,
        send: @escaping SharedMediaNativePhotoEnrichmentAccess.Send) async throws -> SharedMediaNativePhotoAllocation {
        let reserved = try await withReceivingLocks(queueID: prepared.queueID.uuidString,
            observationID: prepared.observationID.uuidString) { lock in
            let operation = try await storage.appPhotoAllocation(grant: grant, lock: lock)
            try grant.validate(); try lock.validate()
            return try operation.reserveRoles(prepared)
        }
        try grant.validate()
        let reply = try await send(reserved, { try grant.validate() })
        try grant.validate()
        return try await withReceivingLocks(queueID: prepared.queueID.uuidString,
            observationID: prepared.observationID.uuidString) { lock in
            let operation = try await storage.appPhotoAllocation(grant: grant, lock: lock)
            try grant.validate(); try lock.validate()
            return try operation.enrich(reply, request: reserved, prepared: prepared)
        }
    }
    /// Inactive local accounting only. No byte read, network callback or release
    /// transition exists here. Exact restart recovery keeps the same held role.
    func reserveAppPhotoTransfer(_ prepared: SharedMediaNativeReceivingIntent.Prepared,
        selection: SharedMediaNativePhotoRoleMapping.Entry) async throws -> SharedMediaNativePhotoAllocation {
        try await withReceivingLocks(queueID: prepared.queueID.uuidString, observationID: prepared.observationID.uuidString) { lock in
            try await self.appPhotoAllocationWorkflow(lock: lock) { try $0.reserveTransfer(prepared, selection: selection) }
        }
    }
